sp_widget.client_script:
api.controller = function($scope, $rootScope, $timeout) {
    var c = this;

    // Carousel state
    c.announcementIndex = 0;
    c.heroSlide = 0;
    c.showJourneyModal = false;
    c.showChatModal = false;
    c.chatInput = '';
    c.chatMessages = [
        { sender: 'ai', text: 'Hello! I am your Warehouse Exception AI Assistant. How can I help you today?' }
    ];
    c.subscribeEmail = '';
    c.subscribeSuccess = false;

    // Auto-rotate announcement
    if (c.data.announcements && c.data.announcements.length > 1) {
        setInterval(function() {
            $scope.$apply(function() {
                c.announcementIndex = (c.announcementIndex + 1) % c.data.announcements.length;
            });
        }, 5000);
    }

    c.nextAnnouncement = function() {
        c.announcementIndex = (c.announcementIndex + 1) % c.data.announcements.length;
    };

    c.prevAnnouncement = function() {
        c.announcementIndex = (c.announcementIndex - 1 + c.data.announcements.length) % c.data.announcements.length;
    };

    // Hero carousel
    c.setHeroSlide = function(idx) {
        c.heroSlide = idx;
    };

    c.nextHeroSlide = function() {
        c.heroSlide = (c.heroSlide + 1) % 2;
    };

    c.prevHeroSlide = function() {
        c.heroSlide = (c.heroSlide - 1 + 2) % 2;
    };

    // Horizontal scroll helper
    c.scrollRow = function(elementId, distance) {
        var el = document.getElementById(elementId);
        if (el) {
            el.scrollBy({ left: distance, behavior: 'smooth' });
        }
    };

    // Navigation
    c.goToReport = function(category, shortDesc) {
        var url = '?id=x_1956908_wareho_0_create';
        if (category) url += '&category=' + encodeURIComponent(category);
        if (shortDesc) url += '&short_desc=' + encodeURIComponent(shortDesc);
        window.location.href = url;
    };

    c.viewDetail = function(sysId) {
        if (!sysId || sysId.startsWith('mock_')) {
            window.location.href = '?id=x_1956908_wareho_0_create';
            return;
        }
        window.location.href = '?id=x_1956908_wareho_0_detail&record_id=' + sysId;
    };

    // Journey modal
    c.openJourney = function() {
        c.showJourneyModal = true;
    };

    c.closeJourney = function() {
        c.showJourneyModal = false;
    };

    // Chat functionality
    c.openChat = function() {
        // Broadcast standard ServiceNow Virtual Agent event if available
        $rootScope.$broadcast('sn-va-open');
        // Also open inline chat helper modal
        c.showChatModal = true;
    };

    c.closeChat = function() {
        c.showChatModal = false;
    };

    c.sendChatMessage = function() {
        if (!c.chatInput || !c.chatInput.trim()) return;
        var text = c.chatInput.trim();
        c.chatMessages.push({ sender: 'user', text: text });
        c.chatInput = '';

        $timeout(function() {
            var lower = text.toLowerCase();
            var reply = 'I have analyzed your request. You can quickly report this issue via the Report Exception form, and our GenAI classifier will automatically determine the severity and owner.';
            if (lower.indexOf('forklift') !== -1 || lower.indexOf('scanner') !== -1 || lower.indexOf('equipment') !== -1) {
                reply = 'This appears to be an Equipment Malfunction. Please log it immediately with the machine ID and bay location.';
            } else if (lower.indexOf('leak') !== -1 || lower.indexOf('damaged') !== -1 || lower.indexOf('crushed') !== -1) {
                reply = 'This is categorized as Damaged Goods. Ensure the area is safe, take a photo if possible, and submit a P1/P2 report.';
            } else if (lower.indexOf('stock') !== -1 || lower.indexOf('missing') !== -1 || lower.indexOf('count') !== -1) {
                reply = 'This matches an Inventory Mismatch exception. Cycle count verification will be initiated.';
            }
            c.chatMessages.push({ sender: 'ai', text: reply });
        }, 600);
    };

    // Subscribe
    c.submitSubscribe = function() {
        if (!c.subscribeEmail || c.subscribeEmail.indexOf('@') === -1) return;
        c.data.action = 'subscribe';
        c.data.email = c.subscribeEmail;
        c.server.update().then(function() {
            c.subscribeSuccess = true;
            c.subscribeEmail = '';
        });
    };
};

sp_widget.css:
@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,700;0,800;1,700&family=DM+Sans:wght@300;400;500;600;700&display=swap');

:root {
  --wei-bg:         #EEECEA;
  --wei-primary:    #5B4BF5;
  --wei-primary-dk: #4438D6;
  --wei-primary-lt: #EAE8FE;
  --wei-text:       #0F0F0F;
  --wei-muted:      #6B6B6B;
  --wei-border:     #D8D4D0;
  --wei-card:       #FFFFFF;
  --wei-radius:     12px;
  --wei-shadow:     0 2px 12px rgba(91,75,245,0.08);
  --wei-success:    #22C55E;
  --wei-warning:    #F59E0B;
  --wei-danger:     #EF4444;
  --wei-info:       #3B82F6;
  --ff-head:        'Playfair Display', Georgia, serif;
  --ff-body:        'DM Sans', -apple-system, BlinkMacSystemFont, sans-serif;
}

body, .sp-widget, .portal-page {
  font-family: var(--ff-body) !important;
  background-color: var(--wei-bg) !important;
  color: var(--wei-text) !important;
}

h1,h2,h3,h4,h5,h6 {
  font-family: var(--ff-head) !important;
}


/* ═══ LANDING PAGE WRAPPER ═══ */
.wei-ecommerce-landing {
  --bg-cream:           var(--wei-bg);
  --primary-olive:      var(--wei-primary);
  --primary-olive-dark: var(--wei-primary-dk);
  --heading-terracotta: var(--wei-primary);
  --text-dark:          var(--wei-text);
  --text-muted:         var(--wei-muted);
  --card-bg:            var(--wei-card);
  --card-radius:        var(--wei-radius);
  --card-shadow:        var(--wei-shadow);
  --sev-critical:       var(--wei-danger);
  --sev-high:           var(--wei-warning);
  --sev-medium:         #FBBF24;
  --sev-low:            var(--wei-success);

  background-color: var(--bg-cream);
  min-height: 100vh;
  font-family: var(--ff-body);
  color: var(--text-dark);
}

/* ═══ ANNOUNCEMENT BAR ═══ */
.wei-announce-bar {
  background: var(--wei-primary);
  color: #fff;
  font-size: 13px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  padding: 9px 0;
  text-align: center;
  font-weight: 600;
  font-family: var(--ff-body);
}
.wei-announce-bar .announce-arrow {
  cursor: pointer;
  opacity: 0.75;
  transition: opacity .2s;
  background: none;
  border: none;
  color: #fff;
  font-size: 14px;
  padding: 0 12px;
}
.wei-announce-bar .announce-arrow:hover { opacity: 1; }

/* ═══ HEADER / NAV ═══ */
.wei-header {
  background: #fff;
  border-bottom: 1.5px solid var(--wei-border);
  padding: 0 24px;
  position: sticky;
  top: 0;
  z-index: 999;
  box-shadow: 0 2px 8px rgba(0,0,0,0.04);
}
.wei-header-inner {
  max-width: 1280px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  height: 60px;
  gap: 24px;
}
.wei-logo-text {
  font-family: var(--ff-head);
  font-size: 19px;
  font-weight: 800;
  color: var(--wei-primary);
  white-space: nowrap;
  letter-spacing: -0.5px;
}
.wei-nav {
  display: flex;
  gap: 4px;
  flex: 1;
  justify-content: center;
  list-style: none;
  margin: 0; padding: 0;
}
.wei-nav li a {
  font-size: 13px;
  font-weight: 600;
  color: var(--wei-text);
  padding: 6px 12px;
  border-radius: 6px;
  text-decoration: none;
  transition: background .2s, color .2s;
  font-family: var(--ff-body);
  letter-spacing: 0.02em;
  text-transform: uppercase;
}
.wei-nav li a:hover,
.wei-nav li.active a {
  background: var(--wei-primary-lt);
  color: var(--wei-primary);
}
.wei-nav li.active a {
  text-decoration: underline;
  text-underline-offset: 3px;
}
.wei-header-icons {
  display: flex;
  align-items: center;
  gap: 12px;
}
.wei-icon-btn {
  width: 36px; height: 36px;
  border-radius: 50%;
  border: 1.5px solid var(--wei-border);
  background: #fff;
  display: flex; align-items: center; justify-content: center;
  cursor: pointer;
  color: var(--wei-text);
  transition: border-color .2s, background .2s;
  font-size: 14px;
  text-decoration: none;
}
.wei-icon-btn:hover {
  background: var(--wei-primary-lt);
  border-color: var(--wei-primary);
  color: var(--wei-primary);
}
.badge-count {
  background: var(--wei-primary);
  color: #fff;
  border-radius: 999px;
  font-size: 10px;
  padding: 1px 5px;
  margin-left: -6px;
  margin-top: -12px;
  font-weight: 700;
  font-family: var(--ff-body);
}
.btn-login-header {
  background: var(--wei-primary) !important;
  color: #fff !important;
  border: none !important;
  border-radius: 8px !important;
  padding: 7px 18px !important;
  font-weight: 700 !important;
  font-size: 13px !important;
  font-family: var(--ff-body) !important;
  letter-spacing: 0.04em !important;
  text-transform: uppercase !important;
  transition: background .2s !important;
  cursor: pointer;
  white-space: nowrap;
}
.btn-login-header:hover { background: var(--wei-primary-dk) !important; }

/* ═══ HERO BANNER ═══ */
.wei-hero {
  background: linear-gradient(135deg, #0F0F0F 0%, #1a1464 60%, var(--wei-primary) 100%);
  min-height: 480px;
  display: flex;
  align-items: center;
  position: relative;
  overflow: hidden;
  padding: 60px 40px;
}
.wei-hero-content {
  max-width: 640px;
  z-index: 2;
  position: relative;
}
.wei-hero-eyebrow {
  font-family: var(--ff-body);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--wei-primary);
  background: rgba(255,255,255,0.1);
  padding: 4px 12px;
  border-radius: 999px;
  display: inline-block;
  margin-bottom: 18px;
  border: 1px solid rgba(255,255,255,0.2);
}
.wei-hero-title {
  font-family: var(--ff-head);
  font-size: clamp(36px, 5vw, 60px);
  font-weight: 800;
  color: #fff;
  line-height: 1.1;
  margin: 0 0 18px 0;
}
.wei-hero-title em {
  font-style: italic;
  color: #A89DFF;
}
.wei-hero-tagline {
  font-family: var(--ff-body);
  font-size: 15px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.75);
  margin: 0 0 32px 0;
  font-weight: 500;
}
.wei-hero-btns {
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
}
.btn-hero-primary {
  background: var(--wei-primary);
  color: #fff;
  border: none;
  border-radius: 8px;
  padding: 14px 28px;
  font-weight: 700;
  font-size: 14px;
  font-family: var(--ff-body);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  cursor: pointer;
  text-decoration: none;
  display: inline-flex; align-items: center; gap: 8px;
  transition: background .2s, transform .2s;
}
.btn-hero-primary:hover {
  background: var(--wei-primary-dk);
  transform: translateY(-2px);
  color: #fff;
  text-decoration: none;
}
.btn-hero-secondary {
  background: transparent;
  color: #fff;
  border: 1.5px solid rgba(255,255,255,0.45);
  border-radius: 8px;
  padding: 13px 24px;
  font-weight: 600;
  font-size: 13px;
  font-family: var(--ff-body);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  cursor: pointer;
  text-decoration: none;
  display: inline-flex; align-items: center; gap: 8px;
  transition: border-color .2s, background .2s;
}
.btn-hero-secondary:hover {
  border-color: #fff;
  background: rgba(255,255,255,0.08);
  color: #fff;
  text-decoration: none;
}
.wei-hero-image {
  position: absolute;
  right: 0; top: 0; bottom: 0;
  width: 45%;
  background: linear-gradient(to left, rgba(0,0,0,0) 0%, transparent 100%);
  display: flex; align-items: center; justify-content: center;
  font-size: 100px;
  opacity: 0.12;
}
.wei-hero-dots {
  display: flex; gap: 8px; margin-top: 32px;
}
.wei-hero-dot {
  width: 8px; height: 8px; border-radius: 50%;
  background: rgba(255,255,255,0.3);
  cursor: pointer; border: none;
  transition: background .2s;
}
.wei-hero-dot.active { background: var(--wei-primary); width: 24px; border-radius: 4px; }

/* ═══ SECTION WRAPPER ═══ */
.wei-section {
  max-width: 1280px;
  margin: 0 auto;
  padding: 56px 24px;
}
.wei-section-eyebrow {
  font-family: var(--ff-body);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--wei-primary);
  margin-bottom: 8px;
}
.wei-section-title {
  font-family: var(--ff-head);
  font-size: clamp(26px, 3vw, 38px);
  font-weight: 800;
  color: var(--wei-text);
  margin: 0 0 40px 0;
  line-height: 1.2;
}
.wei-section-title em {
  font-style: italic;
  color: var(--wei-primary);
}

/* ═══ CATEGORY CARDS ═══ */
.wei-category-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: 20px;
  margin-bottom: 0;
}
.wei-cat-card {
  background: var(--wei-card);
  border-radius: var(--wei-radius);
  padding: 28px 20px 22px;
  text-align: center;
  box-shadow: var(--wei-shadow);
  border: 1.5px solid var(--wei-border);
  cursor: pointer;
  transition: border-color .2s, transform .2s, box-shadow .2s;
  text-decoration: none;
  display: block;
}
.wei-cat-card:hover {
  border-color: var(--wei-primary);
  transform: translateY(-4px);
  box-shadow: 0 8px 24px rgba(91,75,245,0.15);
  text-decoration: none;
}
.wei-cat-icon {
  font-size: 32px;
  color: var(--wei-primary);
  margin-bottom: 12px;
}
.wei-cat-label {
  font-family: var(--ff-body);
  font-size: 13px;
  font-weight: 700;
  color: var(--wei-text);
  margin: 0 0 10px 0;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.wei-cat-link {
  font-size: 12px;
  color: var(--wei-primary);
  font-weight: 600;
  text-decoration: none;
}
.wei-cat-link:hover { text-decoration: underline; }

/* ═══ HORIZONTAL SCROLL CARDS ═══ */
.wei-scroll-track {
  display: flex;
  gap: 20px;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  padding-bottom: 12px;
  -webkit-overflow-scrolling: touch;
}
.wei-scroll-track::-webkit-scrollbar { height: 4px; }
.wei-scroll-track::-webkit-scrollbar-thumb { background: var(--wei-border); border-radius: 2px; }

.wei-exc-card {
  min-width: 240px;
  max-width: 260px;
  background: var(--wei-card);
  border-radius: var(--wei-radius);
  border: 1.5px solid var(--wei-border);
  box-shadow: var(--wei-shadow);
  scroll-snap-align: start;
  flex-shrink: 0;
  overflow: hidden;
  transition: box-shadow .2s, transform .2s;
}
.wei-exc-card:hover {
  box-shadow: 0 8px 24px rgba(91,75,245,0.15);
  transform: translateY(-3px);
}
.wei-exc-card-img {
  height: 130px;
  background: linear-gradient(135deg, var(--wei-primary-lt) 0%, #f0effe 100%);
  display: flex; align-items: center; justify-content: center;
  font-size: 48px;
  color: var(--wei-primary);
  position: relative;
}
.wei-sev-badge {
  position: absolute;
  top: 10px; left: 10px;
  border-radius: 6px;
  font-size: 10px;
  font-weight: 800;
  padding: 3px 9px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-family: var(--ff-body);
}
.wei-sev-badge.critical { background: var(--wei-danger); color: #fff; }
.wei-sev-badge.high     { background: var(--wei-warning); color: #fff; }
.wei-sev-badge.medium   { background: #FBBF24; color: #000; }
.wei-sev-badge.low      { background: var(--wei-success); color: #fff; }

.wei-exc-card-body {
  padding: 16px 16px 14px;
}
.wei-exc-card-type {
  font-size: 10px;
  font-weight: 700;
  color: var(--wei-primary);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: 6px;
  font-family: var(--ff-body);
}
.wei-exc-card-title {
  font-family: var(--ff-body);
  font-size: 13px;
  font-weight: 600;
  color: var(--wei-text);
  margin: 0 0 6px 0;
  line-height: 1.4;
}
.wei-exc-card-meta {
  font-size: 12px;
  font-weight: 700;
  color: var(--wei-primary);
  margin: 0 0 14px 0;
}
.btn-card {
  display: block;
  width: 100%;
  text-align: center;
  border: 1.5px solid var(--wei-text);
  border-radius: 8px;
  padding: 9px 0;
  font-size: 12px;
  font-weight: 700;
  color: var(--wei-text);
  background: transparent;
  font-family: var(--ff-body);
  letter-spacing: 0.05em;
  text-transform: uppercase;
  cursor: pointer;
  text-decoration: none;
  transition: background .2s, color .2s, border-color .2s;
}
.btn-card:hover {
  background: var(--wei-primary);
  color: #fff;
  border-color: var(--wei-primary);
  text-decoration: none;
}

/* ═══ CAROUSEL CONTROLS ═══ */
.wei-carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-top: 24px;
}
.wei-carousel-btn {
  width: 36px; height: 36px;
  border-radius: 50%;
  border: 1.5px solid var(--wei-border);
  background: var(--wei-card);
  color: var(--wei-text);
  display: flex; align-items: center; justify-content: center;
  cursor: pointer;
  transition: border-color .2s, background .2s;
  font-size: 13px;
}
.wei-carousel-btn:hover {
  border-color: var(--wei-primary);
  background: var(--wei-primary-lt);
  color: var(--wei-primary);
}
.wei-carousel-page {
  font-family: var(--ff-body);
  font-size: 13px;
  font-weight: 600;
  color: var(--wei-muted);
}

/* ═══ HOW IT WORKS ═══ */
.wei-howit-card {
  background: var(--wei-card);
  border-radius: 16px;
  padding: 48px;
  box-shadow: var(--wei-shadow);
  border: 1.5px solid var(--wei-border);
}
.wei-step-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 24px;
  margin-top: 32px;
}
.wei-step {
  display: flex;
  gap: 14px;
  align-items: flex-start;
}
.wei-step-num {
  width: 36px; height: 36px;
  border-radius: 50%;
  background: var(--wei-primary);
  color: #fff;
  font-weight: 800;
  font-size: 14px;
  font-family: var(--ff-body);
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
}
.wei-step-label {
  font-family: var(--ff-body);
  font-size: 13px;
  font-weight: 600;
  color: var(--wei-text);
  padding-top: 7px;
}

/* ═══ KPI STATS BAR ═══ */
.wei-stats-bar {
  background: var(--wei-primary);
  padding: 24px 40px;
  display: flex;
  justify-content: space-around;
  flex-wrap: wrap;
  gap: 20px;
  margin: 0;
}
.wei-stat-item {
  text-align: center;
  color: #fff;
}
.wei-stat-num {
  font-family: var(--ff-head);
  font-size: 40px;
  font-weight: 800;
  line-height: 1;
  margin-bottom: 4px;
}
.wei-stat-label {
  font-family: var(--ff-body);
  font-size: 12px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  opacity: 0.85;
}

/* ═══ DIVIDER ═══ */
.wei-divider {
  border: none;
  border-top: 1.5px solid var(--wei-border);
  margin: 0;
}

/* ═══ FOOTER ═══ */
.wei-footer {
  background: var(--wei-text);
  color: rgba(255,255,255,0.8);
  padding: 40px 24px 24px;
}
.wei-footer-inner {
  max-width: 1280px;
  margin: 0 auto;
}
.wei-footer-brand {
  font-family: var(--ff-head);
  font-size: 20px;
  font-weight: 800;
  color: #fff;
  margin-bottom: 6px;
}
.wei-footer-tagline {
  font-size: 12px;
  opacity: 0.6;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  font-family: var(--ff-body);
}
.wei-footer-links a {
  color: rgba(255,255,255,0.7);
  font-size: 13px;
  text-decoration: none;
  margin-right: 20px;
  font-family: var(--ff-body);
  transition: color .2s;
}
.wei-footer-links a:hover { color: #fff; }
.wei-footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  margin-top: 24px;
  padding-top: 16px;
  font-size: 12px;
  opacity: 0.5;
  font-family: var(--ff-body);
}

/* ═══ CHAT BUTTON ═══ */
.wei-chat-fab {
  position: fixed;
  bottom: 24px;
  right: 24px;
  background: var(--wei-text);
  color: #fff;
  border: none;
  border-radius: 999px;
  padding: 12px 20px;
  font-size: 14px;
  font-weight: 700;
  font-family: var(--ff-body);
  cursor: pointer;
  box-shadow: 0 4px 16px rgba(0,0,0,0.25);
  display: flex; align-items: center; gap: 8px;
  transition: background .2s, transform .2s;
  z-index: 9999;
}
.wei-chat-fab:hover {
  background: var(--wei-primary);
  transform: translateY(-2px);
}

/* ═══ LOGIN MODAL ═══ */
.wei-login-overlay {
  position: fixed; inset: 0;
  background: rgba(0,0,0,0.55);
  backdrop-filter: blur(4px);
  z-index: 10000;
  display: flex; align-items: center; justify-content: center;
  padding: 20px;
}
.wei-login-box {
  background: #fff;
  border-radius: 16px;
  padding: 40px 36px;
  max-width: 420px;
  width: 100%;
  box-shadow: 0 24px 64px rgba(0,0,0,0.18);
}
.wei-login-logo {
  font-family: var(--ff-head);
  font-size: 22px;
  font-weight: 800;
  color: var(--wei-primary);
  margin-bottom: 6px;
}
.wei-login-subtitle {
  font-size: 13px;
  color: var(--wei-muted);
  margin-bottom: 28px;
  font-family: var(--ff-body);
}
.wei-login-label {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--wei-text);
  margin-bottom: 6px;
  display: block;
  font-family: var(--ff-body);
}
.wei-login-input {
  width: 100%;
  border: 1.5px solid var(--wei-border);
  border-radius: 8px;
  padding: 11px 14px;
  font-size: 14px;
  font-family: var(--ff-body);
  color: var(--wei-text);
  background: #fff;
  transition: border-color .2s;
  margin-bottom: 16px;
  box-sizing: border-box;
}
.wei-login-input:focus {
  outline: none;
  border-color: var(--wei-primary);
  box-shadow: 0 0 0 3px var(--wei-primary-lt);
}
.wei-login-btn {
  width: 100%;
  background: var(--wei-primary);
  color: #fff;
  border: none;
  border-radius: 8px;
  padding: 13px 0;
  font-size: 14px;
  font-weight: 700;
  font-family: var(--ff-body);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  cursor: pointer;
  margin-top: 4px;
  transition: background .2s;
}
.wei-login-btn:hover { background: var(--wei-primary-dk); }
.wei-login-error {
  background: #FEF2F2;
  border: 1px solid #FECACA;
  border-radius: 8px;
  padding: 10px 14px;
  font-size: 13px;
  color: var(--wei-danger);
  margin-bottom: 16px;
  font-family: var(--ff-body);
}
.wei-login-roles {
  margin-top: 20px;
  padding-top: 16px;
  border-top: 1px solid var(--wei-border);
}
.wei-login-roles-title {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--wei-muted);
  margin-bottom: 10px;
  font-family: var(--ff-body);
}
.wei-role-pill {
  display: inline-block;
  background: var(--wei-primary-lt);
  color: var(--wei-primary);
  border-radius: 999px;
  padding: 4px 12px;
  font-size: 12px;
  font-weight: 600;
  margin: 3px 4px 3px 0;
  font-family: var(--ff-body);
  cursor: pointer;
  border: 1px solid transparent;
  transition: border-color .2s;
}
.wei-role-pill:hover { border-color: var(--wei-primary); }

/* ═══ RESPONSIVE ═══ */
@media (max-width: 768px) {
  .wei-nav { display: none; }
  .wei-hero { padding: 40px 20px; min-height: 340px; }
  .wei-hero-image { display: none; }
  .wei-section { padding: 36px 16px; }
  .wei-howit-card { padding: 24px 16px; }
  .wei-stats-bar { padding: 20px 16px; }
  .wei-login-box { padding: 28px 20px; }
}

sp_widget.script:
(function() {
    var tableName = 'x_1956908_wareho_0_exception';
    var userId = gs.getUserID();

    // 1. Roles & Permissions
    data.isLoggedIn = gs.isLoggedIn();
    data.userName = gs.getUserDisplayName() || 'User';
    data.isSupervisor = gs.hasRole('x_1956908_wareho_0.supervisor') || gs.hasRole('x_1956908_wareho_0.admin') || gs.hasRole('admin');
    data.isTech = gs.hasRole('x_1956908_wareho_0.technician');
    data.isStaff = !data.isSupervisor && !data.isTech;

    if (data.isSupervisor) {
        data.userRole = 'Supervisor';
    } else if (data.isTech) {
        data.userRole = 'Technician';
    } else if (data.isLoggedIn) {
        data.userRole = 'Staff';
    } else {
        data.userRole = 'Guest';
    }

    // 2. Open Exceptions Count for notification badge
    data.openCount = 0;
    try {
        var countGr = new GlideAggregate(tableName);
        countGr.addEncodedQuery('statusINnew,assigned,in_progress');
        countGr.addAggregate('COUNT');
        countGr.query();
        if (countGr.next()) {
            data.openCount = parseInt(countGr.getAggregate('COUNT'), 10) || 0;
        }
    } catch(e) {
        data.openCount = 0;
    }

    // 3. Announcements
    data.announcements = [
        'Report any warehouse exception in under 60 seconds',
        'AI auto-classifies severity and routes to the right owner',
        'Live warehouse intelligence: 95%+ first-cycle resolution rate'
    ];

    // 4. Exception Categories
    data.categories = [
        { id: 'damaged_goods', label: 'Damaged Goods', icon: 'fa-cube' },
        { id: 'inventory_mismatch', label: 'Inventory Mismatch', icon: 'fa-barcode' },
        { id: 'equipment_malfunction', label: 'Equipment Malfunction', icon: 'fa-cogs' },
        { id: 'process_error', label: 'Process Error', icon: 'fa-random' },
        { id: 'safety_incident', label: 'Safety Incident', icon: 'fa-exclamation-triangle' },
        { id: 'other', label: 'Other Exceptions', icon: 'fa-ellipsis-h' }
    ];

    // 5. Most Common Exceptions
    data.commonExceptions = [
        {
            category: 'equipment_malfunction',
            title: 'Barcode Scanner Offline',
            description: 'Connectivity lost during inbound scan cycle at receiving dock.',
            avgTime: '2 hrs',
            icon: 'fa-barcode'
        },
        {
            category: 'inventory_mismatch',
            title: 'Negative Stock Count',
            description: 'Physical shelf count does not match WMS allocation records.',
            avgTime: '3.5 hrs',
            icon: 'fa-calculator'
        },
        {
            category: 'damaged_goods',
            title: 'Pallet Cartons Crushed',
            description: 'Overweight lower racking cartons compromised during storage.',
            avgTime: '4 hrs',
            icon: 'fa-archive'
        },
        {
            category: 'equipment_malfunction',
            title: 'Conveyor Line Jam',
            description: 'Oversized parcels sensor blocking main distribution line.',
            avgTime: '1.5 hrs',
            icon: 'fa-retweet'
        },
        {
            category: 'process_error',
            title: 'Missing Dispatch Papers',
            description: 'Outbound carrier checklist missing customs bill of lading.',
            avgTime: '2.5 hrs',
            icon: 'fa-file-text-o'
        },
        {
            category: 'damaged_goods',
            title: 'Cold Storage Temp Alert',
            description: 'Temperature deviation in Freezer Zone 5 exceeding limits.',
            avgTime: '1 hr',
            icon: 'fa-snowflake-o'
        }
    ];

    // 6. Recently Reported Exceptions (Live data with fallback)
    data.recentExceptions = [];
    var SEV_MAP = {
        'critical': { label: 'Critical', cssClass: 'sev-critical' },
        'high': { label: 'High', cssClass: 'sev-high' },
        'medium': { label: 'Medium', cssClass: 'sev-medium' },
        'low': { label: 'Low', cssClass: 'sev-low' }
    };

    var STATUS_LABEL = {
        'new': 'Open',
        'assigned': 'Assigned',
        'in_progress': 'In Progress',
        'pending': 'Pending',
        'resolved': 'Resolved',
        'closed': 'Closed'
    };

    try {
        var gr = new GlideRecord(tableName);
        gr.orderByDesc('sys_created_on');
        gr.setLimit(9);
        gr.query();

        var nowGdt = new GlideDateTime();

        while (gr.next()) {
            var sevVal = gr.getValue('severity') || 'medium';
            var sevInfo = SEV_MAP[sevVal] || { label: 'Medium', cssClass: 'sev-medium' };
            var stVal = gr.getValue('status') || 'new';

            // Calculate age
            var createdGdt = new GlideDateTime(gr.getValue('sys_created_on'));
            var diffMs = nowGdt.getNumericValue() - createdGdt.getNumericValue();
            var diffMins = Math.max(1, Math.floor(diffMs / 60000));
            var ageText = diffMins < 60 ? (diffMins + ' mins ago') : (Math.floor(diffMins / 60) < 24 ? (Math.floor(diffMins / 60) + ' hrs ago') : (Math.floor(diffMins / 1440) + ' days ago'));

            data.recentExceptions.push({
                sys_id: gr.getUniqueValue(),
                number: gr.getValue('number') || 'EXP',
                short_description: gr.getValue('short_description') || 'Warehouse Exception',
                location: gr.getValue('location') || 'General Warehouse',
                status: STATUS_LABEL[stVal] || stVal,
                assigned_group: gr.getDisplayValue('assignment_group') || gr.getDisplayValue('assigned_to') || 'Operations Team',
                severity: sevInfo.label,
                severityClass: sevInfo.cssClass,
                age: ageText
            });
        }
    } catch(e) {
        gs.error('wei_landing_page: Error reading exceptions: ' + e.message);
    }

    // Fallback if no records yet
    if (data.recentExceptions.length === 0) {
        data.recentExceptions = [
            {
                sys_id: 'mock_1',
                number: 'EXP0001012',
                short_description: 'Forklift Hydraulic Failure at Bay 4',
                location: 'Loading Bay 4',
                status: 'In Progress',
                assigned_group: 'Maintenance Crew',
                severity: 'Critical',
                severityClass: 'sev-critical',
                age: '15 mins ago'
            },
            {
                sys_id: 'mock_2',
                number: 'EXP0001011',
                short_description: 'Cycle count variance SKU-9941',
                location: 'Aisle 14 - Bin 3',
                status: 'Open',
                assigned_group: 'Inventory Control',
                severity: 'High',
                severityClass: 'sev-high',
                age: '1 hr ago'
            },
            {
                sys_id: 'mock_3',
                number: 'EXP0001010',
                short_description: 'Water leak near staging area B',
                location: 'Dispatch Hub B',
                status: 'Assigned',
                assigned_group: 'Facilities Team',
                severity: 'Medium',
                severityClass: 'sev-medium',
                age: '3 hrs ago'
            },
            {
                sys_id: 'mock_4',
                number: 'EXP0001009',
                short_description: 'Missing export customs seal',
                location: 'Dock 7 - Shipping',
                status: 'Resolved',
                assigned_group: 'Compliance Desk',
                severity: 'Low',
                severityClass: 'sev-low',
                age: '1 day ago'
            }
        ];
    }

    // 7. Impact Metrics
    data.impactMetrics = [
        { value: '55%', label: 'Faster Detection', icon: 'fa-bolt' },
        { value: '45%', label: 'Less Manual Triage', icon: 'fa-filter' },
        { value: '50%', label: 'Faster Resolution', icon: 'fa-clock-o' },
        { value: '90%+', label: 'AI Accuracy', icon: 'fa-bullseye' },
        { value: '95%+', label: 'Resolution Rate', icon: 'fa-check-circle' },
        { value: '100%', label: 'Digital Records', icon: 'fa-database' }
    ];

    // 8. 10-Step Journey
    data.journeySteps = [
        { step: 1, title: 'Exception Logged', desc: 'Fast mobile or desktop report in under 60 seconds.' },
        { step: 2, title: 'AI Classification', desc: 'Type and category categorized automatically.' },
        { step: 3, title: 'Severity & Priority', desc: 'P1-P4 priority calculated with SLA target.' },
        { step: 4, title: 'Intelligent Routing', desc: 'Routed to correct technician or queue immediately.' },
        { step: 5, title: 'Instant Notification', desc: 'Supervisor & technician alerted via portal/email.' },
        { step: 6, title: 'Investigation', desc: 'Technician reviews root-cause suggestions & history.' },
        { step: 7, title: 'Resolution Action', desc: 'Physical repair, recount, or quarantine completed.' },
        { step: 8, title: 'Verification & Closure', desc: 'Mandatory resolution notes verified against checklist.' },
        { step: 9, title: 'Resolution Logged', desc: 'Knowledge captured in system of record permanently.' },
        { step: 10, title: 'Analytics & Insights', desc: 'Trends updated live on supervisor dashboard.' }
    ];

    // Handle email subscription
    if (input && input.action === 'subscribe') {
        data.subscribeMessage = 'Thank you! You are now subscribed to exception alerts and weekly summaries.';
    }
})();
